COL = "RGB"


def FT(w):
    """(#R, #G, #B, longest block, number of blocks, length, palindrome, #colours, blocks equal)"""
    G = [len(list(g)) for _, g in itertools.groupby(w)]
    return (w.count("R"), w.count("G"), w.count("B"), max(G), len(G), len(w),
            int(w == w[::-1]), len(set(w)), int(len(set(G)) == 1))


def UNIV():
    """The universe U: 8 kid-sentence templates, 38 concrete rules."""
    U = [(0, i, n) for i in (0, 1, 2) for n in (2, 3, 4, 5)]    # exactly n red / green / blue
    U += [(0, 3, n) for n in (2, 3, 4, 5)]                      # the longest block is n beads
    U += [(0, 4, n) for n in (3, 4, 5, 6, 7)]                   # there are exactly n blocks
    U += [(0, 5, n) for n in (6, 7, 8, 9, 10)]                  # n beads long (competitor only)
    U += [(0, 6, 1), (0, 7, 2), (0, 8, 1)]                      # palindrome / 2 colours / equal blocks
    U += [(1, 0, 1), (1, 0, 2), (1, 2, 1)]                      # as many X beads as Y beads
    U += [(2, i, j) for i in (0, 1, 2) for j in (0, 1, 2) if i != j]   # all X before all Y
    return U


