# The OUTSIDE predicate pool: the 249 bead-string predicates a version-space
# player brings to this world (counts, parities, majorities, runs, blocks,
# substrings, ends, length, symmetry...).  The lineup is balanced against it:
# the true candidate must not stand out as the one that satisfies the most
# example-consistent predicates, which is exactly how v1 was cracked.
# Predicates are grouped by what they read off the string; each group is
# memoised on its own key, so a string costs five dict lookups.
# ---------------------------------------------------------------------------
def PG1(k):                                        # colour counts (B, G, R)
    c = {"B": k[0], "G": k[1], "R": k[2]}
    L = k[0] + k[1] + k[2]
    v = [c[x] == n for x in "BGR" for n in range(12)]
    v += [c[x] == 0 for x in "BGR"]
    v += [b for x in "BGR" for b in (c[x] % 2 == 0, c[x] % 2 == 1)]
    v += [c[x] * 2 > L for x in "BGR"]
    v += [all(c[x] >= c[y] for y in "BGR") for x in "BGR"]
    v += [c[x] == 1 for x in "BGR"]
    v += [c[x] % 3 == 0 for x in "BGR"]
    v += [c[x] * 2 == L for x in "BGR"]
    v += [c[a] == c[b] for a in "BGR" for b in "BGR" if a < b]
    v += [b for a in "BGR" for x in "BGR" if a != x
          for b in (c[a] > c[x], c[a] - c[x] == 1, c[a] - c[x] == 2)]
    v += [sum(1 for n in k if n) == n for n in (1, 2, 3)]
    v += [n in k for n in range(1, 12)]
    v += [L == n for n in range(5, 12)]
    v += [L % 2 == 0, L % 2 == 1, max(k) % 2 == 0]
    return v


def PG2(k):                                        # longest block, number of blocks, length
    x, n, L = k
    v = [b for i in range(1, 12)
         for b in (x == i, x >= i, x <= i, n == i, n <= i, n >= i)]
    v += [n % 2 == 0, n % 2 == 1]
    v += [n - 1 == i for i in range(8)]
    v += [x == 1, x > 1, x * 2 >= L]
    return v


def PG3(k):                                        # per-colour longest block / block count
    v = []
    for i in range(3):
        v += [k[i] < 2, k[i] > 1, k[i + 3] < 2]
        v += [k[i] == n for n in range(1, 8)]
    return v


def PG4(k):                                        # the sequence of block colours
    v = []
    for a in "BGR":
        for b in "BGR":
            if a == b:
                continue
            s = any(k[i] == a and k[i + 1] == b for i in range(len(k) - 1))
            f = [c for c in k if c == a or c == b]
            v += [s, not s,
                  not any(f[i] == b and f[i + 1] == a for i in range(len(f) - 1))]
    v += [b for x in "BGR" for b in (k[0] == x, k[-1] == x, k[0] == x == k[-1])]
    v += [k[0] == k[-1], k[0] != k[-1]]
    return v


def PG5(k):                                        # the sequence of block lengths
    return [len(set(k)) == len(k),
            all(k[i] >= k[i + 1] for i in range(len(k) - 1)), k[0] == k[-1], True]


def PACK(v):
    m = 0
    for i, b in enumerate(v):
        if b:
            m |= 1 << i
    return m


_G = [{}, {}, {}, {}, {}]
_OFF = [0, 105, 184, 214, 243, 247]


def PMASK(w):
    rc = []
    rl = []
    for ch in w:
        if rc and rc[-1] == ch:
            rl[-1] += 1
        else:
            rc.append(ch)
            rl.append(1)
    rc = tuple(rc)
    rl = tuple(rl)
    mx = [0, 0, 0]
    nr = [0, 0, 0]
    for ch, n in zip(rc, rl):
        i = COL.index(ch)
        nr[i] += 1
        if n > mx[i]:
            mx[i] = n
    ks = ((w.count("B"), w.count("G"), w.count("R")), (max(rl), len(rl), len(w)),
          (mx[2], mx[1], mx[0], nr[2], nr[1], nr[0]), rc, rl)
    m = 0
    for i in range(5):
        g = _G[i]
        v = g.get(ks[i])
        if v is None:
            v = PACK((PG1, PG2, PG3, PG4, PG5)[i](ks[i])) << _OFF[i]
            g[ks[i]] = v
        m |= v
    if w == w[::-1]:
        m |= 1 << _OFF[5]
    if w[len(w) // 2] == w[0]:
        m |= 1 << (_OFF[5] + 1)
    return m


def XFEAT(w):
    """What the excluded (trap) rules read: longest block, the three counts, the colour
    set, which colours are doubled, the first and the last bead."""
    G = [len(list(g)) for _, g in itertools.groupby(w)]
    cs = 0
    db = 0
    for i, c in enumerate(COL):
        if c in w:
            cs |= 1 << i
        if c + c in w:
            db |= 1 << i
    return (max(G), w.count("R"), w.count("G"), w.count("B"), cs, db, w[0], w[-1])


def TRAPS(X):
    """The excluded rules that are consistent with every example (X = their features).
    Every one of them is a rule this class NEVER uses; each is a (code, parameter) pair
    read by TBITS below."""
    t = [(0, max(x[0] for x in X))]                      # no block longer than the clue's
    t += [(1, i, min(x[i] for x in X)) for i in (1, 2, 3)]   # at least n red / green / blue
    if len(set(x[4] for x in X)) == 1:
        t.append((2, X[0][4]))                           # exactly the clue's set of colours
    for i in range(3):
        if not any(x[5] >> i & 1 for x in X):
            t.append((3, i))                             # no two C beads ever touch
    if all(x[4] == 7 for x in X):
        t.append((4, 0))                                 # all three colours appear
    for i in (1, 2, 3):
        for j in (1, 2, 3):
            if i != j and all(x[i] > x[j] for x in X):
                t.append((5, i, j))                      # more X beads than Y beads
    if len(set(x[6] for x in X)) == 1:
        t.append((6, X[0][6]))                           # starts with the clue's colour
    if len(set(x[7] for x in X)) == 1:
        t.append((7, X[0][7]))                           # ends with the clue's colour
    if all(x[6] == x[7] for x in X):
        t.append((8, 0))                                 # the two end beads are the same
    if all(x[0] == 1 for x in X):
        t.append((9, 0))                                 # no two beads the same touch
    return t


def TBITS(t, x):
    m = 0
    for k, c in enumerate(t):
        h = c[0]
        if h == 0:
            b = x[0] <= c[1]
        elif h == 1:
            b = x[c[1]] >= c[2]
        elif h == 2:
            b = x[4] == c[1]
        elif h == 3:
            b = not (x[5] >> c[1] & 1)
        elif h == 4:
            b = x[4] == 7
        elif h == 5:
            b = x[c[1]] > x[c[2]]
        elif h == 6:
            b = x[6] == c[1]
        elif h == 7:
            b = x[7] == c[1]
        elif h == 8:
            b = x[6] == x[7]
        else:
            b = x[0] == 1
        if b:
            m |= 1 << k
    return m


