def BUILD(r, g, cand, rho):
    """Assemble the four lines: `rho` of the decoys beat the true candidate on the outside
    predicate count, the rest do not."""
    c, t = r.choice(cand)
    hi = [it for it in g if it[0] > c]
    lo = [it for it in g if it[0] <= c]
    r.shuffle(lo)
    out = [POOL[i] for _, i in hi[:rho] + lo[:3 - rho]] + [POOL[t]]
    r.shuffle(out)
    return out


def LINEUP(r, rule, ex, C, tr):
    """Four candidates of one length, exactly one of which obeys the rule.

    The decoys break the rule but are chosen to satisfy EXACTLY the same excluded rules as the
    true candidate (so no trap - and no count of traps - tells them apart) and to bracket its
    count of example-consistent outside predicates (so the version-space attack that cracked
    v1 - "answer with the thing that satisfies every predicate the clue allows" - has nothing
    to grip: the true candidate is the top scorer of the four only about a quarter of the time).
    """
    b = BIT[rule]
    d = SATL[rule]
    ES = set(ex)
    LS = [x for x in d if len(d[x]) > 8 and len(BYLEN[x]) > 200]
    r.shuffle(LS)
    want = r.randrange(4)                     # the rank we would like the true candidate to take
    back = None
    for L in LS[:2]:
        pool = BYLEN[L]
        n = len(pool)
        sat = d[L]
        ns = len(sat)
        DG = {}
        SG = {}
        seen = set()
        for _s in range(150):                 # decoys: same length, rule broken, one trap fired
            i = pool[r.randrange(n)]
            if i in seen or MSK[i] & b or i in ES:
                continue
            seen.add(i)
            x = TBITS(tr, XFS[i])
            if x:
                DG.setdefault(x, []).append(((PMS[i] & C).bit_count(), i))
        for _s in range(60):                  # true candidates: same length, rule kept
            i = sat[r.randrange(ns)]
            if i in ES:
                continue
            x = TBITS(tr, XFS[i])
            if x in DG:
                SG.setdefault(x, []).append(((PMS[i] & C).bit_count(), i))
        opts = [x for x in SG if len(DG[x]) > 2]
        r.shuffle(opts)
        for x in opts:
            g = DG[x]
            bk = {}
            for c, i in SG[x]:
                k = sum(1 for cc, _ in g if cc > c)
                if k < 4:
                    bk.setdefault(k, []).append((c, i))
            if want in bk:
                return BUILD(r, g, bk[want], want)
            if bk and back is None:
                k = min(bk, key=lambda k: abs(k - want))
                back = (g, bk[k], k)
    if back:
        return BUILD(r, *back)
    return None

